function Ensure-Dir([string]$Path) {
    if (-not (Test-Path $Path)) { New-Item -ItemType Directory -Path $Path | Out-Null }
}

function Write-Utf8([string]$Path, [string]$Content) {
    Ensure-Dir (Split-Path -Parent $Path)
    [System.IO.File]::WriteAllText($Path, $Content, [System.Text.UTF8Encoding]::new($false))
}

function Escape-Json([string]$Value) {
    return $Value.Replace('\', '\\').Replace('"', '\"').Replace("`r", '').Replace("`n", '\n')
}

function Crumb-Json($Crumbs) {
    $items = @()
    for ($i = 0; $i -lt $Crumbs.Count; $i++) {
        $position = $i + 1
        $name = Escape-Json $Crumbs[$i][0]
        $url = "$Base$($Crumbs[$i][1])"
        $items += "{`"@type`":`"ListItem`",`"position`":$position,`"name`":`"$name`",`"item`":`"$url`"}"
    }
    return ($items -join ',')
}

function Crumb-Html($Crumbs) {
    $items = @()
    for ($i = 0; $i -lt $Crumbs.Count; $i++) {
        $crumb = $Crumbs[$i]
        if ($i -eq $Crumbs.Count - 1) {
            $items += "<li><span aria-current=`"page`">$($crumb[0])</span></li>"
        } else {
            $items += "<li><a href=`"$($crumb[1])`">$($crumb[0])</a></li>"
        }
    }
    return ($items -join '')
}

function New-Page {
