        [string]$Path,
        [string]$Title,
        [string]$Description,
        [string]$H1,
        [string]$Eyebrow,
        [string]$Intro,
        [string]$Body,
        [array]$Crumbs,
        [string]$SchemaType = '',
        [string]$SchemaName = '',
        [string]$HeroImage = '',
        [string]$HeroAlt = '',
        [string]$HeroCaption = '',
        [int]$HeroWidth = 600,
        [int]$HeroHeight = 600
    )

    $segments = ($Path.Trim('/') -split '/')
    $depth = $segments.Count
    if ($Path.EndsWith('.html')) { $depth-- }
    if ($Path -eq '/') { $depth = 0 }
    $prefix = if ($depth -eq 0) { './' } else { ('../' * $depth) }
    $canonical = if ($Path -eq '/') { "$Base/" } else { "$Base$Path" }
    if ($Crumbs.Count -gt 0 -and $Crumbs[0] -is [string]) {
        $pairedCrumbs = @()
        for ($i = 0; $i -lt $Crumbs.Count; $i += 2) { $pairedCrumbs += ,@($Crumbs[$i], $Crumbs[$i + 1]) }
        $Crumbs = $pairedCrumbs
    }
    $crumbHtml = Crumb-Html $Crumbs
    $crumbJson = Crumb-Json $Crumbs
    if (-not $HeroImage -and $HeroAssets.ContainsKey($Path)) {
        $asset = $HeroAssets[$Path]
        $HeroImage, $HeroAlt, $HeroCaption, $HeroWidth, $HeroHeight = $asset
    }
    if ($HeroImage) {
        $heroMedia = "<figure class=`"product-visual`"><img src=`"$HeroImage`" width=`"$HeroWidth`" height=`"$HeroHeight`" alt=`"$HeroAlt`" fetchpriority=`"high`"><figcaption>$HeroCaption</figcaption></figure>"
    } else {
        $heroMedia = '<div class="media-diagram" aria-label="Illustration of depth filtration through layered media" role="img"><span class="feed">Process feed</span><i></i><i></i><i></i><span class="filtrate">Clarified filtrate</span></div>'
    }
    $galleryHtml = ''
    if ($GalleryAssets.ContainsKey($Path)) {
        $figures = ''
        foreach ($item in $GalleryAssets[$Path]) {
            $figures += "<figure><img src=`"$($item.src)`" width=`"$($item.width)`" height=`"$($item.height)`" alt=`"$($item.alt)`" loading=`"lazy`" decoding=`"async`"><figcaption>$($item.caption)</figcaption></figure>"
        }
        $galleryHtml = "<section class=`"section section-muted`"><div class=`"shell`"><p class=`"eyebrow`">Original product references</p><h2>Product and system imagery</h2><p class=`"section-intro`">These first-party Sri Bharathi images are retained from the previous website. Grade tables are legacy published references; confirm current availability, tolerances and test methods with the quotation.</p><div class=`"media-gallery`">$figures</div></div></section>"
    }
    $pageSchema = ''
    if ($SchemaType -eq 'Product') {
        $safeName = Escape-Json $SchemaName
        $safeDescription = Escape-Json $Description
        $pageSchema = ", {`"@type`":`"Product`",`"name`":`"$safeName`",`"description`":`"$safeDescription`",`"brand`":{`"@type`":`"Brand`",`"name`":`"Sri Bharathi`"},`"manufacturer`":{`"@id`":`"$Base/#organization`"},`"url`":`"$canonical`"}"
    } elseif ($SchemaType -eq 'Article') {
        $safeName = Escape-Json $SchemaName
        $safeDescription = Escape-Json $Description
        $pageSchema = ", {`"@type`":`"Article`",`"headline`":`"$safeName`",`"description`":`"$safeDescription`",`"author`":{`"@id`":`"$Base/#organization`"},`"publisher`":{`"@id`":`"$Base/#organization`"},`"mainEntityOfPage`":`"$canonical`"}"
    }

    $html = @"
<!doctype html>
<html lang="en-IN">
<head>
