      <div><h2>Applications</h2><a href="${prefix}applications/gelatin-filtration.html">Gelatin filtration</a><a href="${prefix}applications/pharmaceutical-filtration.html">Pharmaceutical filtration</a><a href="${prefix}applications/chemical-filtration.html">Chemical filtration</a><a href="${prefix}applications/food-beverage-filtration.html">Food &amp; beverage</a></div>
