"@

    $file = if ($Path -eq '/') { Join-Path $Root 'index.html' } elseif ($Path.EndsWith('.html')) { Join-Path $Root $Path.TrimStart('/') } else { Join-Path $Root ($Path.Trim('/') + '/index.html') }
    Write-Utf8 $file $html
