function Section([string]$Kicker, [string]$Heading, [string]$Content, [string]$Class = '') {
    return "<section class=`"section $Class`"><div class=`"shell`"><p class=`"eyebrow`">$Kicker</p><h2>$Heading</h2>$Content</div></section>"
}

function Cards($Items) {
    $out = '<div class="card-grid">'
    foreach ($item in $Items) { $out += "<article class=`"card`"><p class=`"card-index`">$($item[0])</p><h3>$($item[1])</h3><p>$($item[2])</p>$($item[3])</article>" }
    return $out + '</div>'
}

function Specs($Rows) {
    $out = '<div class="table-wrap"><table><thead><tr><th>Selection parameter</th><th>Available / verified information</th><th>Engineering relevance</th></tr></thead><tbody>'
    foreach ($row in $Rows) { $out += "<tr><th scope=`"row`">$($row[0])</th><td>$($row[1])</td><td>$($row[2])</td></tr>" }
    return $out + '</tbody></table></div>'
}

function Faqs($Rows) {
    $out = '<div class="faq-list">'
    foreach ($row in $Rows) { $out += "<details><summary>$($row[0])</summary><p>$($row[1])</p></details>" }
    return $out + '</div>'
}

function CTA([string]$Heading, [string]$Text) {
    return "<section class=`"section cta`"><div class=`"shell split`"><div><p class=`"eyebrow`">Application support</p><h2>$Heading</h2><p>$Text</p></div><a class=`"button button-light`" href=`"/contact/`">Request a technical quotation</a></div></section>"
}

function Before-CTA([string]$Body, [string]$Content) {
    return $Body.Replace('<section class="section cta">', $Content + '<section class="section cta">')
}

function Product-Body {
    param([string]$How, [string]$Construction, [array]$Features, [array]$Specs, [string]$Applications, [array]$Faqs, [string]$Related)
    $featureCards = Cards $Features
    $specTable = Specs $Specs
    $faqHtml = Faqs $Faqs
    return @"
$(Section 'Operating principle' 'How the filtration product works' "<div class='prose-grid'><div>$How</div><aside class='note'><strong>Selection starts with the process.</strong><p>State the liquid or gas, operating temperature, target retention, batch volume, viscosity, solids load, housing geometry and cleaning or disposal requirement.</p></aside></div>")
$(Section 'Media design' 'Construction and process behaviour' "<div class='prose'>$Construction</div>" 'section-muted')
$(Section 'What to evaluate' 'Important features and benefits' $featureCards)
$(Section 'Technical data' 'Specification and enquiry checklist' "<p class='section-intro'>Values below are limited to information published by Sri Bharathi. Final grade, compatibility and operating limits must be confirmed against the actual process.</p>$specTable" 'section-muted')
$(Section 'Process fit' 'Applications and selection considerations' "<div class='prose'>$Applications</div>")
$(Section 'Questions engineers ask' 'Frequently asked questions' $faqHtml 'section-muted')
$(Section 'Continue specifying' 'Related filtration products' "<div class='related-links'>$Related</div>")
$(CTA 'Send us your operating conditions' 'Share your fluid, temperature, desired clarity, existing equipment and dimensions. Our team can then recommend a suitable construction and prepare a quotation.')
"@
}

